#include <stdio.h>
#include <limits.h>

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    long long max_val = -9223372036854775807LL;
    for (int i = 0; i < n; i++) {
        long long val;
        scanf("%lld", &val);
        if (val > max_val) max_val = val;
    }
    printf("%lld\n", max_val);
    return 0;
}
